// Versand-Zugang (ALLY 39, BA8, Stefan 20.10.2026; Migration 86, 22.10.2026): Unterablauf nur für ALLY 20 (Einstellungen › Postfächer › Absender für Systemnachrichten
// und „Versand einrichten“ je Postfach-Platz). Setzt die SMTP-Zugangsdaten über die n8n-Schnittstelle (PATCH, Muster ALLY 9), prüft sie (POST …/test) oder leert sie.
// Erlaubt sind der Zugang für Systemnachrichten (fest) und die Versand-Zugänge der eingerichteten Postfächer aus der Datenbank; Eingaben noch einmal prüfen.
// P5 (Aufräumen nach P4): die feste Liste „Postfach-Platz 1–10 – Versand (SMTP)“ ist entfernt (Platz 1–6 stehen seit P4 als eigene Postfächer in der Datenbank).
// Das Passwort steht nur im Eingang und geht nur in den PATCH, nie in eine Ausgabe.
// Plan 56c (Prüfung Fassung 1.0, S1): Installationswert statt fester ID aus der Quell-Installation; das Installationsskript ersetzt den Platzhalter
// (Beipackzettel „installationswerte“). Ohne Ersatz gilt der Wert als nicht gesetzt.
const ERLAUBT = ['__ALLY_ZUGANG_SYSTEMNACHRICHTEN_SMTP__'].filter(x => /^[A-Za-z0-9]{8,40}$/.test(x));
const E = $('Start').first().json || {};
const s = v => String(v ?? '').trim();
const modus = ['speichern', 'pruefen', 'leeren'].includes(s(E.modus)) ? s(E.modus) : '';
// Migration 173 (Schritt P, P3): dazu die Versand-Zugänge der Postfächer mit eigenem Workflow aus der Datenbank (Knoten „Erlaubte Zugänge“)
const DB_IDS = (($('Erlaubte Zugänge').first().json || {}).ids || []).map(String).filter(x => /^[A-Za-z0-9]{8,40}$/.test(x));
const cid = ERLAUBT.includes(s(E.credential_id)) || DB_IDS.includes(s(E.credential_id)) ? s(E.credential_id) : '';
let fehler = '';
if (!modus) fehler = 'Unbekannter Auftrag.';
else if (!cid) fehler = 'Diese Zugangsdaten dürfen hier nicht geändert werden.';
else if (modus === 'speichern') {
  const host = s(E.host).toLowerCase(), port = Number(E.port), ben = s(E.benutzer), pw = String(E.passwort ?? '');
  if (host.length > 253 || !/^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/.test(host)) fehler = 'Der Server ist ungültig.';
  else if (port !== 465 && port !== 587) fehler = 'Der Port ist ungültig.';
  else if (!ben || ben.length > 200 || /[\r\n\t]/.test(ben)) fehler = 'Der Anmeldename ist ungültig.';
  else if (!pw || pw.length > 200) fehler = 'Das Passwort fehlt.';
}
return [{ json: { modus: fehler ? 'abbruch' : modus, auftrag: modus || s(E.modus).slice(0, 20), fehler, credential_id: fehler ? '' : cid } }];

// Antworten der n8n-Schnittstelle zusammenfassen (ALLY 39): modus, patch_status/-meldung, test_status/-meldung, fehler. Nie das Passwort.
const P = $('Prüfen').first().json;
const lauf = n => $(n).isExecuted ? ((($(n).first() || {}).json) || {}) : null;
const t = v => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, 300);
const meld = r => r.error ? t(r.error.message || r.error.description || r.error) : t(((r.body || {}).message) || ('Status ' + r.statusCode));
const setzen = lauf('Zugangsdaten setzen') || lauf('Zugangsdaten leeren');
const test = lauf('Verbindung prüfen (nach Speichern)') || lauf('Verbindung prüfen');
const aus = { modus: P.modus === 'abbruch' ? t(P.auftrag) : P.modus, patch_status: '', patch_meldung: '', test_status: '', test_meldung: '', fehler: t(P.fehler) };
if (setzen) { aus.patch_status = String(setzen.statusCode || ''); if (setzen.statusCode !== 200) aus.patch_meldung = meld(setzen); }
if (test) { const ok = !test.error && (test.body || {}).status === 'OK'; aus.test_status = ok ? 'OK' : 'Error'; aus.test_meldung = ok ? '' : meld(test); }
return [{ json: aus }];
